      "IdContaFinanceira": {param2},
      "IdCategoriaFinanceira": {param3},
      "IdDepartamento": {param4},
      "FormaPagamento": {param5} {
        "Boleto": {param6} {
          "Observacao": {param7}
        },
        "DepositoConta": {param8} {
          "NumeroBanco": {param9},
          "NumeroAgencia": {param10},
          "NumeroConta": {param11}
        },
        "Outros": {param12} {
          "Nome": {param13}
        }
      },
      "PrimeiroVencimento": {param14},
      "DataCompetencia": {param15},
      "QuantidadeParcelas": {param16},
      "Valor": {param17},
      "NumeroDocumento": {param18},
      "Observacao": {param19},
      "ValorDefinitivo": {param20}
}

 ```

